#include "current-helpers.hpp"
int main(){const std::string base="/REQUIRED_EXTERNAL_INPUT/Corsairs/.local-archives/metal-renderer-evidence/world-cut-surface/reopen-production-radius220/";
for(const char*name:{"Antigua-Antigua.bin","Cumana-Cumana.bin"}){auto source=load((base+name).c_str());const auto&t=source.begin()->second[source.begin()->second.size()/2];auto pos=(t[0].position+t[1].position+t[2].position)*(1.f/3);auto n=storm_ship_hull::normalized(storm_ship_hull::cross(t[1].position-t[0].position,t[2].position-t[0].position));auto start=pos+n*.001f;storm_hull_damage::BeamSample b;b.start={start.x,start.y,start.z};b.direction={-n.x,-n.y,-n.z};b.depth=.3f;Cut cut;cut.kind=Cut::Beam;cut.beams={b};cut.field=1;std::set<int>terrain;for(const auto&o:source)terrain.insert(o.first);Mesh out,outer,caps;std::vector<CapPatch>patches;assert(reconstructWorld(source,terrain,{cut},out,&outer,&caps,&patches));const auto center=start-n*.15f;const auto frame=storm_ship_hull::frame(n);unsigned hits=0;for(unsigned k=0;k<8;k++){float a=float(k)*float(M_PI)*.25f;auto direction=frame.tangent*std::cos(a)+frame.bitangent*std::sin(a);double hit=ray(out,center,center+direction);std::cout<<name<<" wall="<<k<<" distance="<<hit<<std::endl;assert(hit>.15&&hit<.18);++hits;}auto floorHit=ray(out,start,start-n);assert(std::abs(floorHit-.3)<.002);std::cout<<name<<" all8walls+finite_floor PASS caps="<<triangleCount(caps)<<std::endl;}}
